// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }
    function testFuzz_property(uint256 amount, address actor, bytes32 hash) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 0, 10 ether);

        vm.deal(actor, amount);
        vm.prank(actor);

        bool ok;
        try c.lockInGuess{value: amount}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || amount == 1 ether);
    }
}
